"""Generate the public, self-contained report from accepted local measurements."""
import html
import json
from pathlib import Path

HERE=Path(__file__).resolve().parent
ROOT=HERE/'results'
summary=json.loads((ROOT/'summary.json').read_text())
environment=json.loads((ROOT/'environment.json').read_text())
cleanup=json.loads((ROOT/'cleanup.json').read_text());assert cleanup['complete']
assert sum(x['measured_calls'] for x in summary.values())==92
labels={'original-q5':'目前模型 Q5','tiro-f16':'Tiro F16 對照','tiro-q5':'Tiro Q5_K_M','tiro-q4':'Tiro Q4_K_M'}
shorts={'original-q5':'原 Q5','tiro-f16':'Tiro F16','tiro-q5':'Tiro Q5','tiro-q4':'Tiro Q4'}
rows=[]
for cid,item in summary.items():
    rows.append({'id':cid,'label':labels[cid],'short':shorts[cid],'groups':item['groups'],
        'latency':item['latency'],'thermal':item['thermal'],
        'quality':item['quality'],'gate':item['versus']['original-q5'],
        'quant_gate':item['versus']['tiro-f16'],'failures':item['failures']})
public={'model':'rohansheth/tiro-qwen3-asr-1.7b-v2',
        'revision':'5dd5f33e0dbaa46254fc552a658d90152f1eaf75','rows':rows,
        'counts':{'quality':56,'latency':36,'total':92},
        'runtime':'existing b7798 Vulkan, ONNX Runtime 1.18 CUDA encoder; test-only libegl1',
        'q5_recipe_matches_original':environment['q5_type_recipe_matches_original'],
        'cleanup_complete':True}
out=HERE/'site';out.mkdir(exist_ok=True)
(out/'measurements.json').write_text(json.dumps(public,ensure_ascii=False,indent=2)+'\n')
(ROOT/'public-comparison.json').write_text(json.dumps(public,ensure_ascii=False,indent=2)+'\n')
base=summary['original-q5'];q4=summary['tiro-q4'];q5=summary['tiro-q5']
speed=100*(1-q4['latency']['mandarin-10s']['wall_s']['p50']/base['latency']['mandarin-10s']['wall_s']['p50'])
table=''
for cid,item in summary.items():
    t=item['thermal'];lat=item['latency']
    table+=f'<tr><th scope="row">{labels[cid]}</th><td>{lat["mandarin-2s"]["wall_s"]["p50"]:.3f}</td><td>{lat["mandarin-5s"]["wall_s"]["p50"]:.3f}</td><td>{lat["mandarin-10s"]["wall_s"]["p50"]:.3f}</td><td>{t["gpu_mib"][0]}–{t["gpu_mib"][1]}</td><td>{"基準" if cid=="original-q5" else "不推薦替換"}</td></tr>'
source='https://huggingface.co/rohansheth/tiro-qwen3-asr-1.7b-v2/blob/5dd5f33e0dbaa46254fc552a658d90152f1eaf75/README.md'
